// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.function.Supplier;
import java.util.stream.Stream;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePlanExecutionProfile.Mode;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * A finite ceiling is a proof, and it can eliminate a rival. A sampled row count and a store's statement count are
 * estimates of what a run will do, so they may set a quote's expectation but never its bounds.
 */
class LmdbNativeUnprovenCeilingTest {

	private static final double UNBOUNDED = LmdbNativeCostQuote.UNBOUNDED_COUNT;

	private static SlotPlan sampled(double rows) {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateRows(null, 0L)).thenReturn(rows);
		return plan;
	}

	private static Stream<Arguments> probingPlans() {
		List<Supplier<SlotPlan>> plans = List.of(
				() -> new LeftJoinPlan(sampled(1D), sampled(1D)),
				() -> new MinusPlan(sampled(1D), sampled(1D), 1L),
				() -> new FilterPlan(sampled(1D), new ExistsFilter(sampled(1D)), 0L));
		return plans.stream().flatMap(plan -> Stream.of(Mode.values()).map(mode -> Arguments.of(plan.get(), mode)));
	}

	@ParameterizedTest
	@MethodSource("probingPlans")
	void aSampledInputDoesNotBoundTheProbesOfOptionalMinusOrExists(SlotPlan plan, Mode mode) {
		LmdbNativeCostVector vector = LmdbNativePlanExecutionProfile.profile(plan, null, 0L, mode);

		assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).as("a sampled quote proves no ceiling")
				.isFalse();
		assertThat(LmdbNativeStaticPrior.DEFAULT.expected(vector)).as("the sample still prices the run")
				.isPositive()
				.isFinite();
	}

	@Test
	void theSimpleProbeQuoteIsNoCeilingEither() {
		for (SlotPlan plan : List.of(new LeftJoinPlan(sampled(1D), sampled(1D)),
				new MinusPlan(sampled(1D), sampled(1D), 1L))) {
			LmdbNativeCostVector vector = LmdbNativeCostVectors.plan(plan, null, 0L, Feature.INTERPRETED_ROW);
			assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).as(plan.getClass().getSimpleName())
					.isFalse();
		}
	}

	@Test
	void anUnknownRowCountIsNotBoundedByTheStatementCount() {
		// a path over 3 edges emits 6 rows: a plan's rows are not statements
		RowState row = LmdbNativeCostVectorsTest.row(3L);

		LmdbNativeCostVector perRow = LmdbNativeCostVectors.perRow(Feature.OUTPUT_MATERIALIZATION, Double.NaN, row);
		assertThat(perRow.high(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(UNBOUNDED);
		assertThat(perRow.expected(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(1.5D);

		LmdbNativeCostVector sweep = LmdbNativeCostVectors.sweep(row, Feature.INTERPRETED_ROW);
		assertThat(sweep.high(Feature.SCANNED_ROW)).isEqualTo(UNBOUNDED);
		assertThat(sweep.expected(Feature.SCANNED_ROW)).isEqualTo(1.5D);
	}

	@Test
	void aPlanningQuoteSetsTheExpectationAndNotTheBounds() {
		LmdbNativeStrategyProposal<String> proposal = new LmdbNativeStrategyProposal<>(() -> "x",
				LmdbNativeWork.atLeast(1D), LmdbNativeWork.ZERO, Double.NaN, "unpriced", () -> {
				}).withPlanningWork(LmdbNativeWork.exact(30D));

		LmdbNativeCostVector total = LmdbNativeStrategyProposal.quote(proposal).total();
		LmdbNativeCostVector sampledOut = LmdbNativeStrategyProposal
				.quote(new LmdbNativeStrategyProposal<>(() -> "x", LmdbNativeWork.exact(30D), LmdbNativeWork.ZERO,
						Double.NaN, "unpriced", () -> {
						}))
				.total();

		assertThat(LmdbNativeStaticPrior.DEFAULT.price(total).known()).isFalse();
		assertThat(LmdbNativeStaticPrior.DEFAULT.expected(total))
				.isEqualTo(LmdbNativeStaticPrior.DEFAULT.expected(sampledOut));
	}

	@Test
	void anEstimateCompetesOnItsExpectationButCannotEliminateARival() {
		LmdbNativeCandidate<String> estimated = LmdbNativeCandidate.of("estimated", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 5D, UNBOUNDED), Double.NaN), () -> "estimated");
		LmdbNativeCandidate<String> proven = LmdbNativeCandidate.of("proven", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, 100D), Double.NaN), () -> "proven");

		LmdbNativeSelector.Ranking ranked = LmdbNativeSelector.rank(List.of(proven, estimated),
				LmdbNativeStaticPrior.DEFAULT, -1D);

		assertThat(ranked.winner()).isEqualTo(1);
		assertThat(ranked.eliminatedBy()).containsOnlyNulls();
		assertThat(ranked.nanos()[1].known()).isFalse();
	}

	@Test
	void aFloorWithNoEstimateIsStillUnpriced() {
		LmdbNativeCandidate<String> floor = LmdbNativeCandidate.of("floor",
				LmdbNativeCostQuote.ofWork(LmdbNativeWork.atLeast(1D), Double.NaN), () -> "floor");
		LmdbNativeCandidate<String> proven = LmdbNativeCandidate.of("proven", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, 100D), Double.NaN), () -> "proven");

		LmdbNativeSelector.Ranking ranked = LmdbNativeSelector.rank(List.of(floor, proven),
				LmdbNativeStaticPrior.DEFAULT, -1D);

		assertThat(ranked.winner()).isEqualTo(1);
		assertThat(ranked.eliminatedBy()[0]).startsWith("Unpriced");
	}
}
